// Vamos usar o $input.all() e assumir que ele está retornando a lista original
// Se o nó anterior retorna a lista completa (o array de objetos)
const inputData = $input.all(); 

const categoriasGeraisUnicas = new Set();

// 1. Processar a lista para extrair apenas nomeCatGeral e remover duplicatas
if (Array.isArray(inputData)) {
    for (const item of inputData) {
        if (item.json && item.json.nomeCatGeral) {
            let nome = item.json.nomeCatGeral.trim();
            // Capitaliza a primeira letra de cada palavra e garante lowercase no resto (para apresentação)
            nome = nome.toLowerCase().split(' ').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
            categoriasGeraisUnicas.add(nome);
        }
    }
} else {
    // Se $input.all() não retornou o array esperado, vamos tentar a simulação
    // Normalmente, esta seção seria removida em produção no n8n.
    // Usaremos a simulação local para garantir que a lógica funciona:
    for (const item of listaDeCategorias) {
        if (item.nomeCatGeral) {
            let nome = item.nomeCatGeral.trim();
            nome = nome.toLowerCase().split(' ').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
            categoriasGeraisUnicas.add(nome);
        }
    }
}

// 2. Formatar a string de saída
const stringFormatada = Array.from(categoriasGeraisUnicas).join('; ');

